// SmartHelmet/Software/src/components/VitalsRadialCard.jsx
import { useMemo } from 'react';
import { RadialBarChart, RadialBar, PolarAngleAxis, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { THRESHOLDS } from '../utils/constants';
import '../styles/VitalsRadialCard.css';

const getColor = (value, thresholds, isHeartRate = false) => {
  if (!value) return '#334155'; // default gray
  if (isHeartRate) {
    if (value <= thresholds.emergencyLow || value >= thresholds.emergencyHigh) return '#ef4444'; // emergency
    if (value <= thresholds.warningLow || value >= thresholds.warningHigh) return '#f59e0b'; // warning
    return '#10b981'; // safe
  } else {
    if (value <= thresholds.emergency) return '#ef4444';
    if (value <= thresholds.warning) return '#f59e0b';
    return '#10b981';
  }
};

const Gauge = ({ value, label, unit, color, max, min = 0, history, dataKey }) => {
  const percentage = Math.min(100, Math.max(0, ((value - min) / (max - min)) * 100));
  const data = [{ name: label, value: percentage, fill: color }];

  const sparklineData = history.map((h, i) => ({ index: i, value: h[dataKey] })).filter(d => d.value != null);

  return (
    <div className="vrc-gauge-container">
      <div className="vrc-gauge-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <RadialBarChart cx="50%" cy="50%" innerRadius="80%" outerRadius="100%" barSize={10} data={data} startAngle={210} endAngle={-30}>
            <PolarAngleAxis type="number" domain={[0, 100]} angleAxisId={0} tick={false} />
            <RadialBar background={{ fill: 'rgba(255, 255, 255, 0.05)' }} dataKey="value" cornerRadius={5} />
          </RadialBarChart>
        </ResponsiveContainer>
        <div className="vrc-gauge-value">
          <span className="vrc-gauge-number">{value || '--'}</span>
          <span className="vrc-gauge-unit">{unit}</span>
        </div>
      </div>
      <div className="vrc-gauge-label">{label}</div>
      <div className="vrc-sparkline">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={sparklineData}>
            <Area type="monotone" dataKey="value" stroke={color} fill={color} fillOpacity={0.2} strokeWidth={2} dot={false} isAnimationActive={false} />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default function VitalsRadialCard({ history }) {
  const latestEntry = history && history.length > 0 ? history[history.length - 1] : null;

  if (!latestEntry) {
    return (
      <div className="vitals-radial-card">
        <div className="vrc-header"><h3 className="vrc-title">Vitals Overview</h3></div>
        <div className="vrc-empty">No data yet</div>
      </div>
    );
  }

  const hrValue = latestEntry.heart_rate;
  const hrColor = getColor(hrValue, THRESHOLDS.heart_rate, true);

  const spo2Value = latestEntry.spo2;
  const spo2Color = getColor(spo2Value, THRESHOLDS.spo2);

  return (
    <div className="vitals-radial-card">
      <div className="vrc-header"><h3 className="vrc-title">Vitals Overview</h3></div>
      <div className="vrc-content">
        <Gauge value={hrValue} label="Heart Rate" unit="bpm" color={hrColor} max={200} min={0} history={history} dataKey="heart_rate" />
        <Gauge value={spo2Value} label="SpO2" unit="%" color={spo2Color} max={100} min={80} history={history} dataKey="spo2" />
      </div>
    </div>
  );
}
